// Exactly-once guard.
// The backend may legitimately deliver the same event twice (e.g. a retry
// after a timeout, or the same session syncing from two devices). We remember
// every eventId in the workflow's static data and drop repeats, so the
// notification fires exactly once per successful session.
const data = $input.first().json;
const payload = data.body ?? data; // webhook v2 wraps the POST body under .body
const eventId = payload.eventId;
if (!eventId) return [];
const staticData = $getWorkflowStaticData('global');
staticData.seen = staticData.seen || {};
if (staticData.seen[eventId]) {
  // duplicate delivery -> stop here, send nothing
  return [];
}
staticData.seen[eventId] = new Date().toISOString();
return [{ json: payload }];
